test('W2.5C10F prioriza accion y resumen movil desplegable',async({page})=>{const {mockPublicApi}=await import('./fixtures/api-mock');await mockPublicApi(page,{authenticated:true});await page.route('**/api/publica/pagos/capacidades',r=>r.fulfill({json:{pagoOnlineDisponible:true,pagoTransferenciaDisponible:true,entornoOnline:'sandbox'}}));await page.goto('/w2/reservar');await page.locator('.reserve-court').first().click();await page.locator('#buscarHorarios').click();await page.locator('.reserve-time').first().click();await page.locator('#aceptarCondiciones').check();await page.locator('#enviarReserva').click();const mobile=await page.evaluate(()=>innerWidth<=620),flow=page.locator('.reserve-flow'),summary=page.locator('.w2-booking-summary'),toggle=page.locator('[data-w2c-summary-toggle]');if(mobile){await expect(toggle).toBeVisible();await expect(toggle).toHaveAttribute('aria-expanded','false');const flowBox=await flow.boundingBox(),summaryBox=await summary.boundingBox();expect(flowBox&&summaryBox&&flowBox.y<summaryBox.y).toBeTruthy();await expect(summary.locator('#resumenLateral')).toBeHidden();await toggle.click();await expect(toggle).toHaveAttribute('aria-expanded','true');await expect(summary.locator('#resumenLateral')).toBeVisible();await toggle.focus();await expect(toggle).toBeFocused()}else await expect(toggle).toBeHidden();const overflow=await page.evaluate(()=>document.documentElement.scrollWidth-innerWidth);expect(overflow).toBeLessThanOrEqual(1)});

test('W2.5C10F FIX conserva ancho util completo en movil',async({page})=>{const {mockPublicApi}=await import('./fixtures/api-mock');await mockPublicApi(page,{authenticated:true});await page.route('**/api/publica/pagos/capacidades',r=>r.fulfill({json:{pagoOnlineDisponible:true,pagoTransferenciaDisponible:true,entornoOnline:'sandbox'}}));await page.goto('/w2/reservar');await page.locator('.reserve-court').first().click();await page.locator('#buscarHorarios').click();await page.locator('.reserve-time').first().click();await page.locator('#aceptarCondiciones').check();await page.locator('#enviarReserva').click();const mobile=await page.evaluate(()=>innerWidth<=900);if(mobile){const geometry=await page.evaluate(()=>{const layout=document.querySelector('.reserve-layout')!.getBoundingClientRect(),flow=document.querySelector('.reserve-flow')!.getBoundingClientRect(),panel=document.querySelector('.reserve-confirmation-panel')!.getBoundingClientRect();return{layoutWidth:layout.width,flowWidth:flow.width,panelWidth:panel.width,leftDelta:Math.abs(flow.left-layout.left),overflow:document.documentElement.scrollWidth-innerWidth}});expect(geometry.flowWidth).toBeGreaterThanOrEqual(geometry.layoutWidth-2);expect(geometry.panelWidth).toBeGreaterThanOrEqual(geometry.layoutWidth-4);expect(geometry.leftDelta).toBeLessThanOrEqual(1);expect(geometry.overflow).toBeLessThanOrEqual(1);const title=page.locator('.reserve-confirmation-title h2');const titleBox=await title.boundingBox();expect(titleBox?.width||0).toBeGreaterThan(180)}const overflow=await page.evaluate(()=>document.documentElement.scrollWidth-innerWidth);expect(overflow).toBeLessThanOrEqual(1)});

test('W2.5C10F FIX 3 conserva etiquetas y resumen semantico movil',async({page})=>{const {mockPublicApi,solicitudCreadaE2E}=await import('./fixtures/api-mock');await mockPublicApi(page,{authenticated:true});await page.addInitScript(({created})=>{sessionStorage.setItem('w2.pago.reserva','901');sessionStorage.setItem('w2.pago.contexto',JSON.stringify({creada:created,fecha:created.fecha}))},{created:{...solicitudCreadaE2E,cancha:'Cancha Central'}});await page.route('**/api/publica/solicitudes/*/pago',r=>r.fulfill({json:{ordenId:701,reservaId:901,estado:'RECHAZADO',metodo:'PAGO_ONLINE',importe:6250,moneda:'ARS',segundosRestantes:420,puedeReintentar:true,puedePagarOnline:true,puedeInformarTransferencia:true}}));await page.goto('/w2/reservar?status=rejected');const mobile=await page.evaluate(()=>innerWidth<=620);if(mobile){const account=page.locator('.w2c-account-action');await expect(account).toContainText('Ver reserva en Mi cuenta');const accountStyle=await account.evaluate(e=>({fontSize:getComputedStyle(e).fontSize,color:getComputedStyle(e).color}));expect(parseFloat(accountStyle.fontSize)).toBeGreaterThanOrEqual(11);const toggle=page.locator('[data-w2c-summary-toggle]');await expect(toggle).toBeVisible();await expect(toggle).toContainText('Cancha Central');await expect(toggle).toContainText('Ver detalles');const toggleStyle=await toggle.evaluate(e=>({background:getComputedStyle(e).backgroundImage,border:getComputedStyle(e).borderColor}));expect(toggleStyle.background).toContain('linear-gradient');expect(toggleStyle.background).not.toContain('rgb(215, 25, 45)');await toggle.click();await expect(toggle).toContainText('Ocultar detalles')}const overflow=await page.evaluate(()=>document.documentElement.scrollWidth-innerWidth);expect(overflow).toBeLessThanOrEqual(1)});

test('W2.5C10G converge estados y resumen movil final',async({page})=>{const {mockPublicApi,solicitudCreadaE2E}=await import('./fixtures/api-mock');await mockPublicApi(page,{authenticated:true});await page.addInitScript(({created})=>{sessionStorage.setItem('w2.pago.reserva','901');sessionStorage.setItem('w2.pago.contexto',JSON.stringify({creada:created,fecha:created.fecha}))},{created:{...solicitudCreadaE2E,cancha:'Cancha Central'}});await page.route('**/api/publica/solicitudes/*/pago',r=>r.fulfill({json:{ordenId:701,reservaId:901,estado:'APROBADA',metodo:'PAGO_ONLINE',importe:6250,moneda:'ARS',segundosRestantes:420}}));await page.goto('/w2/reservar?status=pending');const mobile=await page.evaluate(()=>innerWidth<=620);if(mobile){const toggle=page.locator('[data-w2c-summary-toggle]');await expect(toggle).toHaveAttribute('aria-expanded','false');await expect(toggle).toContainText('Ver detalles');await expect(page.locator('#resumenLateral')).toBeHidden();await expect(page.locator('#irSeguimientoReserva')).toBeHidden();await expect(page.locator('.w2c-account-action')).toHaveCount(1);await toggle.click();await expect(toggle).toContainText('Ocultar detalles')}const overflow=await page.evaluate(()=>document.documentElement.scrollWidth-innerWidth);expect(overflow).toBeLessThanOrEqual(1)});

test('W2.5C10G presenta reserva creada sin acreditacion en curso',async({page})=>{const {mockPublicApi}=await import('./fixtures/api-mock');await mockPublicApi(page,{authenticated:true});await page.route('**/api/publica/complejo',r=>r.fulfill({json:{moneda:'ARS',colorPrincipal:'#d7192d',anticipacionMinimaHoras:2,minutosReservaPendiente:10,porcentajeSenia:25,pagoOnlineDisponible:false,pagoTransferenciaDisponible:false}}));await page.route('**/api/publica/pagos/capacidades',r=>r.fulfill({json:{pagoOnlineDisponible:false,pagoTransferenciaDisponible:false}}));await page.goto('/w2/reservar');await page.locator('.reserve-court').first().click();await page.locator('#buscarHorarios').click();await page.locator('.reserve-time').first().click();await page.locator('#aceptarCondiciones').check();await page.locator('#enviarReserva').click();const empty=page.locator('.w2c-no-methods');await expect(empty).toBeVisible();await expect(empty).toContainText('No hay medios de pago disponibles ahora');await expect(empty).toContainText('No vuelvas a reservar el mismo horario');await expect(empty.locator('a')).toHaveAttribute('href',/reserva=901/);await expect(page.locator('[data-pay-online],[data-pay-manual]')).toHaveCount(0);await expect(page.locator('.w2-booking-summary')).toHaveAttribute('data-payment-state','created');await expect(page.locator('#estadoReservaLateral')).toHaveText('Reserva creada');const mobile=await page.evaluate(()=>innerWidth<=620);if(mobile)await expect(page.locator('[data-w2c-summary-toggle]')).toHaveAttribute('aria-expanded','false');const overflowG=await page.evaluate(()=>document.documentElement.scrollWidth-innerWidth);expect(overflowG).toBeLessThanOrEqual(1)});


test('pago invitado usa seguimiento publico sin exigir sesion',async({page})=>{let perfil=0,pagoPublico=0;await page.route('**/api/publica/cliente/perfil',r=>{perfil++;return r.fulfill({status:401,json:{mensaje:'No autenticado'}})});await page.route('**/api/publica/pagos/capacidades',r=>r.fulfill({json:{pagoOnlineDisponible:false,pagoTransferenciaDisponible:true}}));await page.route('**/api/publica/solicitudes/*/pago',r=>{pagoPublico++;return r.fulfill({status:201,json:{ordenId:801,reservaId:901,estado:'ESPERANDO_VERIFICACION',metodo:'TRANSFERENCIA_MANUAL',importe:6250,moneda:'ARS',segundosRestantes:420,puedeInformarTransferencia:true}})});await page.goto('/w2/reservar');await page.locator('.reserve-court').first().click();await page.locator('#buscarHorarios').click();await page.locator('.reserve-time').first().click();await page.locator('#formReserva').evaluate((form:HTMLFormElement)=>{for(const [id,value] of Object.entries({clienteNombre:'Ana',clienteApellido:'Prueba',clienteDocumento:'30123456',clienteTelefono:'1112345678'})){const input=form.querySelector<HTMLInputElement>('#'+id);if(input)input.value=value}});await page.locator('#aceptarCondiciones').check();await page.locator('#enviarReserva').click();await page.locator('[data-pay-manual]').click();await expect(page.locator('.reserve-confirmation-shell.manual')).toBeVisible();expect(perfil).toBe(0);expect(pagoPublico).toBe(1)});

test('F2A adopta identidad premium sin alterar el flujo',async({page})=>{await page.goto('/w2/reservar');await expect(page.locator('html')).toHaveClass(/w2-booking-page/);await expect(page.locator('.w2b2-hero')).toBeVisible();await expect(page.locator('.reserve-steps [data-paso-indicador]')).toHaveCount(4);await expect(page.locator('.reserve-court').first()).toBeVisible();await expect(page.locator('.w2-booking-summary')).toBeVisible();const accent=await page.locator('#buscarHorarios').evaluate(e=>getComputedStyle(e).backgroundImage);expect(accent).toContain('linear-gradient')});
test('F2A elimina el verde como identidad dominante',async({page})=>{await page.goto('/w2/reservar');await page.locator('.reserve-court').first().click();const border=await page.locator('.reserve-court.selected').evaluate(e=>getComputedStyle(e).borderColor);expect(border).toBe('rgb(229, 39, 66)');const principal=await page.evaluate(()=>getComputedStyle(document.documentElement).getPropertyValue('--color-principal').trim());expect(principal).toBe('#d7192d')});
